const icons={sword:'M4 20 17 7m-6 1 5 5M16 4l4 0 0 4-6 6-4-4 6-6ZM3 17l4 4',fire:'M12 3c1 5-5 6-5 11a5 5 0 0 0 10 0c0-2-1-4-3-6 0 3-2 3-2 4 1-4 2-6 0-9Z',check:'m5 12 4 4L19 6',arrow:'M4 12h15m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',target:'M21 12a9 9 0 1 1-9-9m0 5a4 4 0 1 0 4 4m-4 0 8-8m-4 0h4v4',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',hammer:'m4 20 9-9m-4-5 5-3 7 7-3 5-9-9Z',camp:'M3 20 12 4l9 16H3Zm5 0 4-7 4 7',bag:'M5 7h14l2 14H3L5 7Zm3 0V5a4 4 0 0 1 8 0v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 4 2 3v4l4 3 3-1 3 1 4-3v-4l2-3-2-4-3-1-1-3H9Z',volume:'M4 9h4l5-5v16l-5-5H4V9Zm12-2q6 5 0 10',edit:'m4 16 11-11 4 4L8 20H4v-4Zm9-9 4 4',undo:'M8 4 3 9l5 5M3 9h10a6 6 0 0 1 0 12',close:'m6 6 12 12M6 18 18 6',star:'m12 3 3 6 6 1-4 5 1 6-6-3-6 3 1-6-4-5 6-1 3-6Z',scroll:'M6 3h14v14H8a3 3 0 0 0-3 3V6a3 3 0 0 0-3-3h4Zm2 14v4h12a3 3 0 0 0 3-3v-1h-3M9 7h7M9 11h7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',more:'M4.5 12a1.5 1.5 0 1 0 3 0 1.5 1.5 0 1 0-3 0M10.5 12a1.5 1.5 0 1 0 3 0 1.5 1.5 0 1 0-3 0M16.5 12a1.5 1.5 0 1 0 3 0 1.5 1.5 0 1 0-3 0',week:'M4 6h16v14H4ZM4 10h16M8 3v5m8-5v5',skip:'M5 5l8 7-8 7V5Zm11 0v14',stop:'M6 6h12v12H6Z',archive:'M4 8h16v12H4ZM3 4h18v4H3ZM10 12h4',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[name]||icons.star).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`}
let artSequence=0;
const STEEL=[['#343e45','#7f8682','#3b454c','#4a5357','#8f9494'],['#2e3840','#c0c9c6','#3b454c','#5e6a70','#c3ccce'],['#3a302d','#d9a47c','#4a3530','#6d4c3e','#de915c'],['#4a3f2a','#f3d79e','#5a4a30','#8c7649','#ebc884']];
const CAPE=['#4d3b38','#7a3a34','#8e2f2c'],SCARF=['#51423f','#8a4c3f','#9b3b33'];
function blades(family,stage,edge){const e=`stroke="${edge}"`;if(family==='dual'){const pair=['<path d="m160 110 24-57 6-3-2 20-20 44Z" fill="url(#P-steel)" '+e+'/><path d="M62 172 27 135l-2-15 15 7 31 39Z" fill="url(#P-steel)" '+e+'/>','<path d="m159 110 26-63 8-4-2 24-21 45Z" fill="url(#P-steel)" '+e+'/><path d="M62 172 24 133l-4-18 18 8 33 41Z" fill="url(#P-steel)" '+e+'/>'];return pair[stage>0?1:0]+(stage>=2?'<path d="m167 104 20-48M57 165 30 133" stroke="#f0a060" stroke-width="1.6" opacity=".85"/>':'')+(stage>=3?'<path d="m186 46 7-9 1 12ZM22 116l-6-8 11 2Z" fill="#f3d79e"/>':'')}
const shape=['<path d="m155 102 21-64 7-8 3 13-22 65Z" fill="url(#P-steel)" '+e+'/><path d="m170 64 5-3-1 8-4 2" fill="#2a2e32"/>','<path d="m154 102 19-76 11-10 7 17-24 74Z" fill="url(#P-steel)" '+e+'/><path d="m176 34 7-10-20 73" fill="none" stroke="#e1e6dc" opacity=".5"/>','<path d="m154 102 19-76 11-10 7 17-24 74Z" fill="url(#P-steel)" '+e+'/><path d="m177 33 6-9-21 74" fill="none" stroke="#f0a060" stroke-width="1.8" opacity=".9"/>','<path d="m152 106 20-77 9-9 3 17 11-2-3 14-12 10 3 11-15 39Z" fill="url(#P-steel)" '+e+'/><path d="m176 43-16 57" stroke="#f0b77a" stroke-width="2"/>'];return shape[stage]}
/* family: 'great' | 'dual'. tier changes the blade, cape and light at the milestones in game.js. */
function knight(family='great',tier=0,large=false){const P='knight'+(++artSequence)+'-',look=EmberGame.gearLook(tier),st=STEEL[look.blade],trim=look.cape>1?'#d1a75e':'#6b5149',scarf=SCARF[look.cape];
const halo=look.glow>=2?`<g class="halo" opacity="${look.glow>2?.85:.55}"><circle cx="110" cy="70" r="46" fill="url(#P-aura)"/><circle cx="110" cy="66" r="38" fill="none" stroke="${look.glow>2?'#ffd99a':'#e8b477'}" stroke-width="2"/><circle cx="110" cy="66" r="31" fill="none" stroke="#e8b477" stroke-dasharray="2 6" opacity=".7"/></g>`:'';
const aura=look.glow>=3?'<ellipse cx="110" cy="150" rx="105" ry="125" fill="url(#P-aura)" opacity=".55"/>':'';
const sparks=look.glow>=2?'<g fill="#f4c27c" class="sparks"><circle cx="176" cy="40" r="1.6"/><circle cx="190" cy="70" r="1.1"/><circle cx="60" cy="60" r="1.2"/><circle cx="168" cy="20" r="1"/></g>':'';
let svg=`<g class="knight ${large?'large':''}"><defs><linearGradient id="P-steel" x1="0" x2="1"><stop stop-color="${st[0]}"/><stop offset=".48" stop-color="${st[1]}"/><stop offset=".55" stop-color="${st[2]}"/><stop offset="1" stop-color="${st[3]}"/></linearGradient><linearGradient id="P-armor" x1="0" x2="1"><stop stop-color="#111a23"/><stop offset=".45" stop-color="#4d5961"/><stop offset=".7" stop-color="#232c36"/><stop offset="1" stop-color="#090e16"/></linearGradient><linearGradient id="P-cape" x2="1" y2="1"><stop stop-color="${CAPE[look.cape]}"/><stop offset="1" stop-color="#12171e"/></linearGradient><radialGradient id="P-aura"><stop stop-color="#f2b56c" stop-opacity=".55"/><stop offset="1" stop-color="#f2b56c" stop-opacity="0"/></radialGradient><filter id="P-glow" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur in="SourceAlpha" stdDeviation="${look.glow>2?5:3.2}" result="b"/><feFlood flood-color="#f2a45a" flood-opacity="${look.glow>2?1:.85}"/><feComposite in2="b" operator="in" result="g"/><feMerge><feMergeNode in="g"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>${aura}${halo}<ellipse cx="113" cy="261" rx="76" ry="9" fill="#070a0e" opacity=".7"/><path class="cloak" d="M82 81 61 95 52 155 24 240l24-6-1 17 25-12 6 15 32-20 24 18 8-19 29 8-9-25-12-119-29-19Z" fill="url(#P-cape)" stroke="${trim}" stroke-width="${look.cape>1?2.2:.6}"/><path d="m68 109-10 107-15 24m39-127-7 114m61-119 10 105 13 21" fill="none" stroke="#82695b" opacity=".18" stroke-width="2"/><path d="m86 189-9 45-7 15 4 10h31l-1-11 9-45m17-14 16 40-2 22 7 10h28l-6-14-15-56" fill="url(#P-armor)" stroke="#606970" stroke-width="1.3"/><path d="m81 228 23 6m30-6 21-7m-75 19 22 3m39-10 15-5" stroke="#74808a" opacity=".65"/><path d="M80 115 81 174 71 198l38 9 40-10-14-26 4-57Z" fill="url(#P-armor)" stroke="#737c7c"/><path d="m81 139 30 12 27-15-4 32-22 14-29-14Z" fill="#1e2932" stroke="#626c71"/><path d="m89 126 21 10 19-8m-42 54 25 7 24-8m-29-40 1 35" stroke="#8b9390" opacity=".55" fill="none"/><path d="m74 94-20 17 6 26 22-9 8-22Zm53 1 25 13 7 23-23-1-17-23Z" fill="url(#P-armor)" stroke="#8c928a"/><path d="m57 115 22-8m51-3 21 10m-86 3 7 5m60-7 10 4" stroke="#b3a68d" opacity=".65"/><path d="m59 134-6 29 10 17 13-7-1-13 7-31m66 4 13 23 2 21-12 11-11-7 5-17-11-26" fill="url(#P-armor)" stroke="#6d797f"/><path d="m56 160 17 4m70-7 17-4" stroke="#a2a79b"/><path d="M88 91 84 60l12-19 29 3 13 20-9 31-22 9Z" fill="url(#P-armor)" stroke="#8e978e"/><path d="m94 45 4-13 7 10 15 2 9-7-2 12" fill="#313b45" stroke="#a09a85"/><path d="m88 64 21 7 23-6-7 10-18 6-18-6Z" fill="#070d13"/><path d="m109 49-2 22-1 23m-12-12 8 5m14-5 8-4" stroke="#b0b5a8" opacity=".65"/><path d="m95 58 7 2m13 2 10-2" stroke="#bba881" opacity=".7"/><path d="m77 101 10-8 24 14 20-14 10 11-20 17-26-4Z" fill="${scarf}" stroke="${look.cape>1?'#d1a75e':'#8b6953'}"/><path d="m79 175 58 2 1 7-58-1Z" fill="#5c5043" stroke="#b5a27c"/><rect x="105" y="176" width="12" height="9" fill="#212a32" stroke="#bfa778"/><g class="blade" ${look.glow?'filter="url(#P-glow)"':''}>${blades(family,look.blade,st[4])}<path d="m145 102 28 9 2 5-33-10Z" fill="#ad9270" stroke="#433c33"/><path d="m157 111-6 21 5 2 7-21Z" fill="#493d33" stroke="#ad9270"/></g><path d="m150 123 10 4-2 11-11-3Z" fill="#647078" stroke="#8d968b"/>${look.blade>=3?'<path d="m80 105 8 4-4 8-7-3Z" fill="#efb571"/>':''}${sparks}</g>`;
return svg.replaceAll('P-',P)}
function enemyArt(region,hp,phase=-1){if(hp<=0)return '';const colors=['#847a69','#a5abb9','#b79875'];let body=region===1?'<path d="M20 130Q20 38 76 26Q134 40 136 130l-20-20-5 33-20-13-15 20-18-23-20 16-3-33Z" fill="#3a4052" stroke="#9195a2"/><path d="m59 56 17-17 18 20-9 22H67Z" fill="#0a111c"/><path d="m67 60 8 3m7 0 7-3" stroke="#dbc8a4" stroke-width="2"/><path d="M25 111q50-27 100 0M42 88q40-17 65 0" fill="none" stroke="#717b8e"/>':region===2?'<path d="m21 40 29 17 24-18 25 18 32-17-6 67-31-17-19 43-20-43-30 18Z" fill="#292b35" stroke="#756c66"/><path d="m56 62 17-30 19 30-12 24H67Z" fill="#111720" stroke="#aa9472"/><path d="m60 47-4-20 14 9 5-18 8 18 13-10-5 24m-28 12 9 3 11-3" fill="none" stroke="#c1a67b"/><path d="m66 88-13 53 23-8 21 9-15-54" fill="#3e3533" stroke="#9a7c64"/>':'<path d="m44 67-19 18 5 34 20-7-5 43h62l-7-43 20 7 5-34-22-18-29 7Z" fill="#292e35" stroke="#737474"/><path d="m49 83 25 13 27-13-3 33-23 12-25-13Z" fill="#41454b" stroke="#787973"/><path d="m57 74-6-29 23-17 24 17-7 29-18 9Z" fill="#30353b" stroke="#8a897c"/><path d="m54 44-11-18 18 9m32 8 14-19-17 11" fill="#383b41" stroke="#7c7b70"/><path d="m61 51 10 4 17-5" fill="none" stroke="#d4a46d" stroke-width="2"/><path d="M119 80h9l5 70h-17Z" fill="#77756c" stroke="#3e4349"/><path d="m111 120 26-1v5h-26Z" fill="#aa8d63"/>';
const boss=phase>=0,crack=boss&&phase>=1?`<g class="cracks" stroke="#ff9a5a" stroke-width="${phase>=2?2.4:1.6}" fill="none" stroke-linejoin="bevel" opacity=".9"><path d="m60 70 9 8-5 7 10 6-3 9"/><path d="m95 92-8 10 6 5-9 12"/>${phase>=2?'<path d="m44 118 12-6 3 9 11-4M101 56l-7 9 5 4"/>':''}</g>`:'';
const shards=boss&&phase>=2?'<g fill="#3a3f46" stroke="#8a8a80"><path d="m8 150 14-9 6 11Z"/><path d="m120 152 9-12 9 10Z"/><path d="m140 145 6-5 4 7Z"/></g>':'';
const eyes=boss&&phase>=1?`<g fill="${phase>=2?'#ff5a3a':'#ff9a5a'}"><circle cx="68" cy="58" r="2.2"/><circle cx="84" cy="58" r="2.2"/></g>`:'';
const aura=boss&&phase>=2?'<ellipse cx="77" cy="92" rx="78" ry="74" fill="#d2462e" opacity=".16"/><ellipse cx="77" cy="92" rx="56" ry="56" fill="#ff8a4a" opacity=".1"/>':'';
const stance=!boss?'':phase>=2?'translate(4 12) rotate(-9 77 150)':phase>=1?'translate(2 5) rotate(-4 77 150)':'';
return `<g class="enemy-figure ${boss?'boss phase-'+phase:''}" opacity="${boss?1:Math.max(.45,hp)}"><ellipse cx="77" cy="155" rx="61" ry="9" fill="#050910"/>${aura}${shards}<g transform="${stance}">${body}${crack}${eyes}</g><path d="m68 97-5 15m29-25-6 11" stroke="${colors[region]}" opacity="${1-hp}" stroke-width="2"/></g>`}
function sceneArt(region,family,tier,game){let r=EmberGame.REGIONS[region],encounter=EmberGame.currentEncounter(game,region),ratio=encounter.maxHp?encounter.hp/encounter.maxHp:0,clear=game.cleared[region],prog=game.stages[region]/4,isBoss=encounter.kind==='boss',phase=isBoss?EmberGame.bossPhase(encounter.hp,encounter.maxHp):-1;let sky=phase===2?'#4a1f1c':phase===1?'#3a2a2c':region===2?'#4b3733':region===1?'#24283a':'#292d35';let env='';if(region===0){env=`<path d="M40 290V70h90V15h230v55h90v220Z" fill="#151b24" stroke="#51545a"/><path d="M58 290V93h57v197m260 0V93h58v197" fill="#272e36" stroke="#454b51"/><path d="M143 290V140Q245-25 347 140v150" fill="#0c131e" stroke="#646263" stroke-width="9"/><path d="M160 290V143Q245 11 330 143v147" fill="${clear?'#baa078':'#171f2a'}" stroke="#3b444d" stroke-width="4"/>${!clear?`<g opacity="${1-prog*.6}"><path d="M176 290V144m23 146V116m23 174V100m24 190V94m23 196V100m23 190V115m23 175V144" stroke="#53595f" stroke-width="6"/><path d="M170 166h150m-150 54h150m-150 47h150" stroke="#40474e" stroke-width="5"/></g>`:'<path d="m245 140-55 150h110Z" fill="#ead5a0" opacity=".24"/>'}<path d="M137 70h216M137 86h216M57 132h57m262 0h56M57 200h57m262 0h56" stroke="#5a5d60" opacity=".4"/><path d="m120 17 18 30-12 25m206-53-20 23 10 23" stroke="#080f19" fill="none" stroke-width="4"/>`}
if(region===1)env='<path d="M10 300V92l70-53 72 53v208M350 300V92l70-53 72 53v208" fill="#171d2b" stroke="#424854"/><path d="M114 300V44L245-10l130 54v256" fill="#202533" stroke="#59606b"/><path d="M173 300V107Q245-1 317 107v193" fill="#0b1320" stroke="#747582" stroke-width="5"/><path d="M215 124V61h59v63Z" fill="#5b5c67"/><path d="M229 120V66h31v54Z" fill="#c3b09a" opacity=".4"/><path d="M126 300V61h20v239m198 0V61h21v239M33 300V108h22v192m389 0V108h22v192" fill="#3e4350"/><path d="M0 283h500M0 300h500m-400-150h76m164 0h70" stroke="#5a5b67" opacity=".5"/><path d="m289 15-20 31 15 22-13 44m-110 91 20 20-5 50" stroke="#0a111e" fill="none" stroke-width="5"/>';
if(region===2)env='<circle cx="258" cy="93" r="56" fill="#c0a284" opacity=".5"/><path d="M0 201 92 100l53 51 63-68 45 58 67-100 89 129 91-89v219H0Z" fill="#34323a"/><path d="M0 248 82 158l79 69 55-61 70 91 91-81 123 54v70H0Z" fill="#24262f"/><path d="m122 290 24-116 62 14 12 98m89 13-12-101 35-24 28 116" fill="#111b25" stroke="#5d5354"/><path d="m135 191 70 16m-74 9 80 16m93-17 35-12" stroke="#74605b"/><path d="M240 300V130l18-16 19 16v170" fill="#30303a" stroke="#9c8267"/><path d="m245 138 12 8 16-8m-26 13 8 7 15-7" stroke="#c1a078" fill="none"/>';
return `<svg viewBox="0 0 700 430" role="img" aria-label="${r.name}。${family==='dual'?'双剣':'大剣'}を携えた灰の旅人と${clear?'灯った烽火':encounter.enemy}${isBoss?'（'+EmberGame.PHASES[phase]+'）':''}" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="night" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="#090f17"/></linearGradient><radialGradient id="light"><stop stop-color="#c99465" stop-opacity=".4"/><stop offset="1" stop-color="#c99465" stop-opacity="0"/></radialGradient><linearGradient id="mist"><stop stop-color="#bbc2c0" stop-opacity="0"/><stop offset=".5" stop-color="#bbc2c0" stop-opacity=".13"/><stop offset="1" stop-color="#bbc2c0" stop-opacity="0"/></linearGradient></defs><rect width="700" height="430" fill="url(#night)"/><circle cx="495" cy="85" r="140" fill="url(#light)"/><g transform="translate(175 0)">${env}</g>${phase>=1?`<rect width="700" height="430" fill="#c2412c" opacity="${phase>=2?.12:.06}"/>`:''}${phase>=2?'<g stroke="#f6b673" stroke-width="3" opacity=".32" class="rays"><path d="M500 260 420 40M520 260l40-230M540 270l150-150M480 270 330 120"/></g><g fill="#ff9a5a" class="embers" opacity=".8"><circle cx="470" cy="200" r="2"/><circle cx="560" cy="170" r="1.6"/><circle cx="600" cy="230" r="1.3"/><circle cx="430" cy="150" r="1.4"/><circle cx="520" cy="120" r="1.1"/></g>':''}<path d="M0 321 48 302l60 14 62-9 52 18 87-15 62 16 78-13 81 12 71-19 99 19v105H0Z" fill="#101820"/><path d="M290 430 383 311h47l-48 119" fill="#626165" opacity=".12"/><g transform="translate(430 195) scale(1.05)">${encounter.kind==='cache'?'<g transform="translate(20 80)"><path d="M10 30Q10 0 57 0q45 0 45 30v38H10Z" fill="#4e3f32" stroke="#b39a6e" stroke-width="2"/><path d="M10 30h92M25 4v63M87 4v63" stroke="#b39a6e" stroke-width="4"/><rect x="50" y="26" width="13" height="20" fill="#dbc18b"/><ellipse cx="57" cy="28" rx="50" ry="22" fill="url(#light)"/></g>':`<g transform="translate(${encounter.kind==='boss'?-45:0} ${encounter.kind==='boss'?-62:0}) scale(${encounter.kind==='boss'?1.48:encounter.index===0?.8:1.12})">${enemyArt(region,ratio,phase)}</g>`}</g><g class="hero-stage" transform="translate(105 102) scale(1.18)"><path d="m72 96 16-35 18-20 24 5 17 34 17 32 13 93-7 46" fill="none" stroke="#d8b585" stroke-opacity=".32" stroke-width="3"/>${knight(family,tier)}</g><g opacity=".16" stroke="#c4c3b7" stroke-width=".6"><path d="m232 266 17 7m-19-3 15 8m35-6 8-11m-5 13 6-9m-44 27 12 3"/></g><ellipse class="mist" cx="420" cy="328" rx="420" ry="40" fill="url(#mist)"/><path d="m0 390 120-13 120 21 140-15 120 13 200-15v49H0Z" fill="#080f16"/><g transform="translate(77 316)"><path d="m-7 50 14-3m-17-1 18 6" stroke="#5e4a37" stroke-width="5"/><path class="flame" d="M0 44q-12-12-3-26-1 9 5 11 8-13 3-23 22 25 6 38Z" fill="${clear?'#f4be70':'#b67847'}"/><path d="M2 43q-5-9 2-15 8 12 3 15Z" fill="#f2ca88"/></g>${clear?'<g fill="#c69253"><path d="M608 291v-27q-13-9-3-23l4 8 6-20q17 25 4 35v27Z"/><path d="M146 218v-23q-10-7-2-20l4 6 3-17q15 20 4 31v23Z"/></g>':''}<g fill="#d9a16c" opacity=".65" class="embers"><circle cx="89" cy="319" r="1.2"/><circle cx="72" cy="304" r=".9"/><circle cx="113" cy="341" r="1.1"/><circle cx="58" cy="336" r=".8"/><circle cx="355" cy="371" r=".8"/></g><path class="slash" d="M350 107Q600 200 465 345" stroke="#f4c588" stroke-width="7" fill="none"/><path class="slash second" d="M585 139Q377 253 554 342" stroke="#f4c588" stroke-width="4" fill="none"/></svg>`}
